\section{Method}
\label{sec:method}

\begin{figure*}[t]
\begin{minipage}[t]{0.46\textwidth}
\centering
\scriptsize
\setlength{\tabcolsep}{4pt}
\begin{tabular}{@{}rrr@{}}
\toprule
